    "top_hashtags": ["common hashtags"],
    "opportunities_for_client": ["2-3 specific opportunities based on trends"],
    "key_takeaways": ["3-5 actionable insights"]
  },
  "instagram_trends_analysis": {
    "overview": "Brief summary",
