// Build Normalized Client Object - UPDATED: multi-geo, multi-language, brand_voice
const allItems = $input.all();
const config = $('Workflow Configuration').first().json;
const clientData = $('Combine Brief Context with Client Data').first().json;

console.log('');
console.log('═══════════════════════════════════════════════════════');
console.log('Building Normalized Client Object');
console.log(`Received ${allItems.length} items from Merge node`);
console.log('═══════════════════════════════════════════════════════');

// Debug
allItems.forEach((item, idx) => {
  const json = item.json;
  const source = json.source || (json.profiles ? 'sprout' : 'unknown');
  console.log(`   [${idx}] source="${source}" _empty=${json._empty || false}`);
});

// Find Sprout Data
let sproutData = {
  profiles: [], platform_metrics: {}, platform_breakdown: [], top_posts: [],
  top_posts_by_platform: {}, overall_totals: {}, reporting_period: {}, month_comparison: {}
};

for (const item of allItems) {
  const json = item.json;
  if (json.profiles !== undefined || json.month_comparison !== undefined || json.overall_totals !== undefined) {
    sproutData = json;
    console.log('✅ Found Sprout data');
    break;
  }
}

// Find TikTok Trends - FILTER OUT empty placeholders
const tiktokTrends = allItems
  .filter(item => item.json.source === 'tiktok' && !item.json._empty)
  .map(item => item.json);
console.log(`✅ Found ${tiktokTrends.length} TikTok trends`);

// Find Instagram Trends - FILTER OUT empty placeholders
const instagramTrends = allItems
  .filter(item => item.json.source === 'instagram' && !item.json._empty)
  .map(item => item.json);
console.log(`✅ Found ${instagramTrends.length} Instagram trends`);

// Filter to client's profiles
const clientProfileIds = (clientData.sprout_profile_ids || '').toString().split(',')
  .map(id => parseInt(id.trim(), 10)).filter(id => !isNaN(id));

let clientProfiles = sproutData.profiles || [];
if (clientProfileIds.length > 0) {
  clientProfiles = clientProfiles.filter(profile => clientProfileIds.includes(profile.id));
}
console.log(`✅ Filtered to ${clientProfiles.length} client profiles`);

// Analyze patterns in trends
function analyzePatterns(trends) {
  const patterns = { common_hashtags: {}, avg_engagement: 0, top_hashtags: [] };
  if (trends.length === 0) return patterns;

  let totalEngagement = 0;
  trends.forEach(trend => {
    (trend.hashtags || []).forEach(tag => {
      const cleanTag = tag.toLowerCase().replace(/^#/, '');
      patterns.common_hashtags[cleanTag] = (patterns.common_hashtags[cleanTag] || 0) + 1;
    });
    totalEngagement += trend.engagement_score || 0;
  });

  patterns.avg_engagement = Math.round(totalEngagement / trends.length);
  patterns.top_hashtags = Object.entries(patterns.common_hashtags)
    .sort((a, b) => b[1] - a[1]).slice(0, 10).map(([tag, count]) => ({ tag, count }));

  return patterns;
}

const tiktokPatterns = analyzePatterns(tiktokTrends);
const instagramPatterns = analyzePatterns(instagramTrends);

// === MULTI-GEO: ensure array ===
let geoArr = clientData.geo || ['US'];
if (typeof geoArr === 'string') geoArr = geoArr.split(',').map(s => s.trim()).filter(Boolean);
if (!Array.isArray(geoArr)) geoArr = [geoArr];

// === MULTI-LANGUAGE: ensure array ===
let languagesArr = clientData.languages || clientData.language || ['en'];
if (typeof languagesArr === 'string') languagesArr = languagesArr.split(',').map(s => s.trim()).filter(Boolean);
if (!Array.isArray(languagesArr)) languagesArr = [languagesArr];

// === BRAND VOICE ===
const brandVoice = clientData.brand_voice || '';
const brandBookText = clientData.brand_book_text || '';

// Build output
const normalizedClient = {
  client_name: clientData.client_name || 'Unknown Client',
  report_window: {
    current_month: clientData.date_ranges?.current_month
      || sproutData.reporting_period?.current_month
      || { start: config.current_month_start, end: config.current_month_end },
    previous_month: clientData.date_ranges?.previous_month
      || sproutData.reporting_period?.previous_month
      || { start: config.previous_month_start, end: config.previous_month_end }
  },
  context: {
    geo: geoArr,
    languages: languagesArr,
    timezone: clientData.timezone || 'UTC',
    brand_voice: brandVoice,
    brand_book_text: brandBookText,
    primary_platforms: typeof clientData.primary_platforms === 'string'
      ? clientData.primary_platforms.split(',').map(p => p.trim())
      : (clientData.primary_platforms || ['Instagram', 'TikTok', 'LinkedIn']),
    brand_notes: clientData.brand_notes || '',
    brief_context: clientData.brief_context || {},
    content_pillars: clientData.content_pillars || [],
    design_style_synthesis: clientData.design_style_synthesis || null,
    has_design_references: Array.isArray(clientData.design_references) && clientData.design_references.length > 0,
    has_brand_book: !!clientData.brand_book_file_path,
  },
  skip_trends: !!(clientData.skip_trends),
  sprout: {
    profiles: clientProfiles,
    platform_metrics: sproutData.platform_metrics || {},
    overall_totals: sproutData.overall_totals || {},
    top_posts: sproutData.top_posts || [],
    month_comparison: sproutData.month_comparison || {},
    platform_breakdown: sproutData.platform_breakdown || [],
    top_posts_by_platform: sproutData.top_posts_by_platform || {}
  },
  trends: {
    tiktok: { posts: tiktokTrends, patterns: tiktokPatterns },
    instagram: { posts: instagramTrends, patterns: instagramPatterns }
  },
  _meta: {
    tiktok_count: tiktokTrends.length,
    instagram_count: instagramTrends.length,
    profiles_count: clientProfiles.length,
    generated_at: new Date().toISOString()
  }
};

console.log('');
console.log('═══════════════════════════════════════════════════════');
console.log(`✅ Built for: ${normalizedClient.client_name}`);
console.log(`   Geo: [${geoArr.join(', ')}] | Languages: [${languagesArr.join(', ')}]`);
console.log(`   Brand Voice: ${brandVoice || 'none'}`);
console.log(`   Brand Book: ${brandBookText ? 'provided (' + brandBookText.length + ' chars)' : 'none'}`);
console.log(`   TikTok: ${tiktokTrends.length} | Instagram: ${instagramTrends.length}`);
console.log(`   Sprout top posts: ${sproutData.top_posts?.length || 0}`);
console.log(`   Sprout profiles: ${clientProfiles.length}`);
console.log('═══════════════════════════════════════════════════════');

return [{ json: normalizedClient }];

// Normalize Instagram Trends - FIXED: language source, relevance scoring, spam filtering, date filtering
const rawItems = $input.all();

// ── Get target languages from Combine Brief Context (NOT Workflow Configuration!) ──
let targetLangs = ['en'];
let clientKeywords = [];
let trendsStartDate = '';

try {
  const clientData = $('Combine Brief Context with Client Data').first().json;

  // Languages
  const rawLangs = clientData.languages || clientData.language || ['en'];
  if (Array.isArray(rawLangs)) {
    targetLangs = rawLangs.map(l => l.toLowerCase().slice(0, 2));
  } else {
    targetLangs = String(rawLangs).split(',').map(l => l.trim().toLowerCase().slice(0, 2)).filter(Boolean);
  }

  // Client keywords for relevance scoring
  const socialArr = Array.isArray(clientData.social_keywords) ? clientData.social_keywords : [];
  const trendsRaw = clientData.trends_keywords || '';
  const trendsArr = typeof trendsRaw === 'string' ? trendsRaw.split(',').map(k => k.trim()) : (Array.isArray(trendsRaw) ? trendsRaw : []);
  clientKeywords = [...new Set([...socialArr, ...trendsArr])].filter(Boolean).map(k => k.toLowerCase().replace(/^#/, ''));

  // Date range
  trendsStartDate = clientData.date_ranges?.current_month?.start || '';
} catch(e) {
  console.log('⚠️ Could not get client data from Combine Brief Context:', e.message);
}
if (targetLangs.length === 0) targetLangs = ['en'];

console.log('═══════════════════════════════════════════════════════');
console.log('Normalizing Instagram Trends');
console.log(`Target languages: [${targetLangs.join(', ')}]`);
console.log(`Client keywords for relevance: [${clientKeywords.join(', ')}]`);
console.log(`Raw posts received: ${rawItems.length}`);
console.log('═══════════════════════════════════════════════════════');

// ── Language detection ──
const LANG_WORDS = {
  en: ['the','and','for','you','this','that','with','have','are','was','will','your','from','how','what','when','get','can','all','just','not','but','more','like','new','business','marketing','content','brand','social','media','digital','tips','follow'],
  es: ['que','los','las','del','por','una','con','para','como','pero','mas','todo','esta','tiene','hay','son','fue','muy','tambien','sobre'],
  fr: ['les','des','une','pour','dans','que','est','sur','pas','plus','avec','sont','tout','fait','mais','comme'],
  de: ['und','der','die','das','ist','ein','fur','mit','den','von','nicht','sich','auf','dem','auch','noch'],
  pt: ['que','para','com','uma','por','mais','como','mas','dos','das','tem','sao','foi','nao'],
  ar: [], he: [], ja: [], ko: [], zh: [], it: [], ru: [], hi: [], th: [],
};

const SCRIPT_PATTERNS = {
  ar: /[\u0600-\u06FF\u0750-\u077F]/,
  he: /[\u0590-\u05FF]/,
  ja: /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FFF]/,
  ko: /[\uAC00-\uD7AF\u1100-\u11FF]/,
  zh: /[\u4E00-\u9FFF\u3400-\u4DBF]/,
  ru: /[\u0400-\u04FF]/,
  hi: /[\u0900-\u097F]/,
  th: /[\u0E00-\u0E7F]/,
};

function matchesTargetLanguage(text, lang) {
  if (!text || text.length < 10) return false;
  const cleanText = text.replace(/#\w+/g, '').replace(/@\w+/g, '')
    .replace(/[\u{1F600}-\u{1F6FF}]/gu, '').replace(/[\u{2600}-\u{26FF}]/gu, '').trim();
  if (cleanText.length < 5) return false;
  if (SCRIPT_PATTERNS[lang]) return SCRIPT_PATTERNS[lang].test(cleanText);
  const nonLatinPattern = /[\u0600-\u06FF\u0750-\u077F\u0590-\u05FF\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FF\uAC00-\uD7AF\u0E00-\u0E7F\u0900-\u097F\u0400-\u04FF]/;
  if (nonLatinPattern.test(cleanText)) return false;
  const words = LANG_WORDS[lang] || LANG_WORDS['en'];
  if (words.length === 0) return true;
  const lowerText = cleanText.toLowerCase();
  return words.filter(word => lowerText.includes(word)).length >= 2;
}

function matchesAnyTargetLanguage(text, langs) {
  return langs.some(lang => matchesTargetLanguage(text, lang));
}

// ── Spam/scam detection ──
const SPAM_SIGNALS = [
  /\b(crypto|bitcoin|btc|ethereum|eth|nft|airdrop|binance|coinbase|token|defi|web3|blockchain|solana|memecoin)\b/i,
  /\b(casino|poker|slots?|betting|bet365|jackpot|roulette)\b/i,
  /\b(f4f|l4l|follow\s*for\s*follow|like\s*for\s*like|follow\s*back|gain\s*followers|free\s*followers)\b/i,
  /\b(onlyfans|18\+|nsfw|xxx|sex|nude|dating\s*site)\b/i,
  /\b(make\s*money\s*fast|passive\s*income\s*\d|earn\s*\$?\d{4,}|work\s*from\s*home\s*\$|financial\s*freedom\s*secret)\b/i,
  /\b(link\s*in\s*bio.*free|dm\s*for\s*price|limited\s*offer|act\s*now)\b/i,
];

function isSpam(caption, hashtags) {
  const fullText = caption + ' ' + (hashtags || []).join(' ');
  let spamScore = 0;
  for (const pattern of SPAM_SIGNALS) {
    if (pattern.test(fullText)) spamScore++;
  }
  if ((hashtags || []).length > 15 && caption.length < 100) spamScore += 2;
  const emojiCount = (caption.match(/[\u{1F600}-\u{1F6FF}\u{1F900}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu) || []).length;
  if (emojiCount > 15) spamScore++;
  return spamScore >= 2;
}

// ── Relevance scoring against client keywords ──
function getRelevanceScore(caption, hashtags) {
  if (clientKeywords.length === 0) return 1;
  const fullText = (caption + ' ' + (hashtags || []).join(' ')).toLowerCase();
  let matches = 0;
  for (const kw of clientKeywords) {
    if (fullText.includes(kw) || fullText.includes(kw.replace(/\s+/g, ''))) {
      matches++;
    }
  }
  return matches / Math.max(clientKeywords.length, 1);
}

const normalizedItems = rawItems
  .map(item => {
    const data = item.json;
    if (data.type === 'carousel_item') return null;

    const likes = data.likesCount || data.likes || 0;
    const comments = data.commentsCount || data.comments || 0;
    const views = data.videoViewCount || data.views || 0;
    const safeLikes = likes === -1 ? 0 : likes;
    const engagementScore = (safeLikes * 1) + (comments * 2) + Math.floor(views / 1000);
    const caption = data.caption || data.text || '';

    let url = data.url || '';
    if (!url && data.shortCode) {
      url = `https://www.instagram.com/p/${data.shortCode}/`;
    }

    const author = data.ownerUsername || data.owner?.username || data.author || 'unknown';
    let hashtags = [];
    if (data.hashtags && Array.isArray(data.hashtags)) {
      hashtags = data.hashtags.map(h => typeof h === 'string' ? h : (h.name || '')).filter(Boolean);
    }
    const postType = data.type || data.__typename || (data.videoUrl ? 'Video' : 'Image');

    // Language check
    const passesLangFilter = matchesAnyTargetLanguage(caption, targetLangs);

    // Spam check
    const spamFlag = isSpam(caption, hashtags);

    // Relevance check
    const relevance = getRelevanceScore(caption, hashtags);

    // Date check — IG scraper has no date filter, so we filter here
    let passesDateFilter = true;
    const postTimestamp = data.timestamp || data.takenAtTimestamp || 0;
    if (trendsStartDate && postTimestamp) {
      try {
        // postTimestamp can be Unix seconds or ISO string
        const postDate = typeof postTimestamp === 'number'
          ? new Date(postTimestamp * 1000)
          : new Date(postTimestamp);
        const startDate = new Date(trendsStartDate);
        startDate.setDate(startDate.getDate() - 30); // Allow 30 days before period start
        if (postDate < startDate) passesDateFilter = false;
      } catch(e) {}
    }

    return {
      source: 'instagram', url, caption, author, hashtags,
      engagement_score: engagementScore,
      likes: safeLikes, comments, views,
      type: postType,
      created: data.timestamp || data.takenAtTimestamp || '',
      matches_language: passesLangFilter,
      is_spam: spamFlag,
      relevance_score: relevance,
      passes_date: passesDateFilter
    };
  })
  .filter(item => {
    if (!item) return false;
    if (!item.url || item.url.length < 10) return false;
    if (!item.matches_language) return false;
    if (item.is_spam) return false;
    if (!item.passes_date) return false;
    if (clientKeywords.length > 0 && item.relevance_score === 0) return false;
    return true;
  })
  // Sort by relevance first, then engagement
  .sort((a, b) => {
    const relDiff = b.relevance_score - a.relevance_score;
    if (Math.abs(relDiff) > 0.2) return relDiff;
    return b.engagement_score - a.engagement_score;
  })
  .slice(0, 15);

console.log(`Filtered to ${normalizedItems.length} posts (lang: ${targetLangs.join('/')}, spam-free, relevant)`);

if (normalizedItems.length > 0) {
  console.log('Top 3 Instagram posts:');
  normalizedItems.slice(0, 3).forEach((item, i) => {
    console.log(`  ${i+1}. @${item.author} | Score: ${item.engagement_score.toLocaleString()} | Relevance: ${(item.relevance_score * 100).toFixed(0)}%`);
  });
}

if (normalizedItems.length === 0) {
  console.log(`No relevant ${targetLangs.join('/')} Instagram posts found -- returning placeholder`);
  return [{
    json: {
      source: 'instagram', url: '',
      caption: `No relevant ${targetLangs.join('/')} Instagram posts found for these keywords`,
      author: 'none', hashtags: [], engagement_score: 0,
      likes: 0, comments: 0, views: 0,
      type: 'none', created: '', matches_language: true,
      rank: 0, _empty: true
    }
  }];
}

return normalizedItems.map((item, idx) => ({ json: { ...item, rank: idx + 1 } }));

// Normalize TikTok Trends - FIXED: language source, relevance scoring, spam filtering, date filtering
const rawItems = $input.all();

// ── Get target languages from Combine Brief Context (NOT Workflow Configuration!) ──
let targetLangs = ['en'];
let clientKeywords = [];
let trendsStartDate = '';
let trendsEndDate = '';

try {
  const clientData = $('Combine Brief Context with Client Data').first().json;

