    const data = item.json;
    const likes = data.diggCount || data.likes || 0;
    const comments = data.commentCount || data.comments || 0;
    const shares = data.shareCount || data.shares || 0;
    const views = data.playCount || data.views || 0;
    const engagementScore = (likes * 1) + (comments * 2) + (shares * 3) + Math.floor(views / 1000);
    const caption = data.desc || data.text || data.caption || '';
    let url = data.webVideoUrl || data.url || '';
    if (!url && data.authorMeta?.name && data.id) {
      url = `https://www.tiktok.com/@${data.authorMeta.name}/video/${data.id}`;
    }
    const author = data.authorMeta?.name || data.author || 'unknown';
    const hashtags = (data.hashtags || []).map(h => typeof h === 'string' ? h : (h.name || '')).filter(Boolean);

    // Language check
    const textLang = (data.textLanguage || '').toLowerCase();
    let passesLangFilter = false;
    if (targetLangs.includes(textLang)) {
      passesLangFilter = true;
    } else {
      passesLangFilter = matchesAnyTargetLanguage(caption, targetLangs);
    }

    // Spam check
    const spamFlag = isSpam(caption, hashtags);

    // Relevance check
    const relevance = getRelevanceScore(caption, hashtags);

    // Date check
    let passesDateFilter = true;
    if (trendsStartDate && data.createTimeISO) {
      try {
        const postDate = new Date(data.createTimeISO);
        const startDate = new Date(trendsStartDate);
        startDate.setDate(startDate.getDate() - 30); // Allow 30 days before period start for trends
        if (postDate < startDate) passesDateFilter = false;
      } catch(e) {}
    }

    return {
      source: 'tiktok', url, caption, author, hashtags,
      engagement_score: engagementScore,
      views, likes, comments, shares,
      created: data.createTimeISO || data.createTime || '',
      matches_language: passesLangFilter,
      is_spam: spamFlag,
      relevance_score: relevance,
      passes_date: passesDateFilter,
      is_ad: data.isAd || data.isSponsored || false
    };
  })
  .filter(item => {
    if (!item.url || item.url.length < 10) return false;
    if (!item.matches_language) return false;
    if (item.is_ad) return false;
    if (item.is_spam) return false;
    if (!item.passes_date) return false;
    // Require minimum relevance: at least 1 keyword match (if keywords exist)
    if (clientKeywords.length > 0 && item.relevance_score === 0) return false;
    return true;
  })
