// Sprout DOES carry post media. analytics/posts returns visual_media[] with
// thumbnail_url and media_type (verified live against a Bader Law TikTok post);
// the request simply never asked for it. Without it every monthly top post
// reached the report with no image, and the app fell back to scraping the
// permalink, which Instagram and TikTok mostly refuse.
//
// The thumbnail is re-attached here by joining on the permalink, rather than
// inside the aggregation above, so that 18KB of working code is left alone.
// The urls are signed and expire after roughly two months, which is fine for a
// report that is read in the weeks after it is generated.
const raw = [];
for (const name of ['Get Sprout Social Post Analytics', 'Get Previous Month Post Analytics']) {
  try {
    for (const item of $(name).all()) {
      const list = item.json && Array.isArray(item.json.data) ? item.json.data : [];
      for (const p of list) raw.push(p);
    }
  } catch (e) { /* that call did not run on this execution */ }
}
const byLink = new Map();
for (const p of raw) {
  // One empty row in Sprout's data[] would otherwise throw here and take the
  // entire monthly report with it. A missing thumbnail is worth nothing; a
  // failed report costs the whole run.
  if (!p || typeof p !== 'object') continue;
  const link = String(p.perma_link || p.url || '');
  const media = Array.isArray(p.visual_media) ? p.visual_media[0] : null;
  if (link && media && media.thumbnail_url) byLink.set(link, media);
}
const stamp = (post) => {
  const m = byLink.get(String(post.permalink || post.url || ''));
  if (!m) return;
  if (!post.thumbnail_url) post.thumbnail_url = m.thumbnail_url;
  if (!post.media_type) post.media_type = m.media_type || '';
};
const walk = (v, depth) => {
  if (depth > 8 || !v || typeof v !== 'object') return;
  if (Array.isArray(v)) { for (const x of v) walk(x, depth + 1); return; }
  if (v.permalink || v.url) stamp(v);
  for (const k of Object.keys(v)) walk(v[k], depth + 1);
};
return $input.all().map((item) => { walk(item.json, 0); return { json: item.json }; });

